3	/**
4	 * Numeric membership level for pet owners, from 1 to 3. Every owner starts at level 1; the level
5	 * gains 1 when the owner has an email address (non-null, non-blank) and a further 1 when its
6	 * {@code namesakeCount} is 0 (no existing owner shares its first and last name), capped at 3. Level
7	 * 4 is reserved for tenure and is not awarded here. Derived purely from the owner's own stored state
8	 * ({@code namesakeCount} is recorded at create time), so it is seed-independent. Used by the owner
9	 * mapper to expose {@code membershipLevel} on responses.
10	 */
11	public final class MembershipLevel {
12	
13	    private MembershipLevel() {
14	    }
15	
16	    /**
17	     * The membership level for the given namesake count and email: 1 to start, +1 when the email is
18	     * present (non-null, non-blank), +1 when the namesake count is exactly 0, capped at 3.
19	     */
20	    public static int of(Integer namesakeCount, String email) {
21	        int level = 1;
22	        boolean hasEmail = email != null && !email.isBlank();
23	        if (hasEmail) {
24	            level++;
25	        }
26	        boolean unique = namesakeCount != null && namesakeCount == 0;
27	        if (unique) {
28	            level++;
29	        }
30	        return Math.min(level, 3);
31	    }
32	}
