1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Step of {@code POST /api/owners} that flags a soft duplicate. A new owner that is not a hard
9	 * duplicate (see {@link RequireUniqueIdentity}) but shares an existing owner's last name and
10	 * postcode while having a different telephone is a <em>possible</em> duplicate: it is still created,
11	 * but {@code possibleDuplicate} is set {@code true} and {@code possibleDuplicateOf} to the matching
12	 * owner's id. Otherwise {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf} is
13	 * left unset.
14	 *
15	 * <p>Last name is compared case-insensitively; postcode must be present and equal; the telephone is
16	 * compared in its canonical form so an owner with the same telephone (a hard duplicate) is not
17	 * flagged here. When several existing owners match, the one with the lowest id (the earliest) is
18	 * reported. Runs after {@link BuildOwner} so the owner's telephone is already normalized, and before
19	 * {@link SaveOwner} so the owner being created is not compared against itself.
20	 */
21	public class FlagPossibleDuplicate {
22	
23	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
24	        String lastName = owner.getLastName();
25	        String postcode = owner.getPostcode();
26	        String telephone = OwnerIdentity.normalizedTelephone(owner.getTelephone());
27	        Integer matchId = null;
28	        if (postcode != null && !postcode.isBlank()) {
29	            for (Owner existing : ownerRepository.findAll()) {
30	                if (existing.getId() == null || !lastName.equalsIgnoreCase(existing.getLastName())
31	                        || !postcode.equals(existing.getPostcode())) {
32	                    continue;
33	                }
34	                if (telephone.equals(OwnerIdentity.normalizedTelephone(existing.getTelephone()))) {
35	                    continue; // same telephone: a hard duplicate, not a possible one
36	                }
37	                if (matchId == null || existing.getId() < matchId) {
38	                    matchId = existing.getId();
39	                }
40	            }
41	        }
42	        owner.setPossibleDuplicate(matchId != null);
43	        owner.setPossibleDuplicateOf(matchId);
44	    }
45	}
