1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * Step of {@code POST /api/owners} that rejects a create whose derived identity (see
11	 * {@link OwnerIdentity}) collides with an existing owner's, throwing {@link DuplicateIdentityException}
12	 * (handled as 409 Conflict). This is the single, consolidated duplicate check that replaces the
13	 * former separate telephone, email and household checks: they are all expressed through the one
14	 * {@code identityKey}. Because the telephone is part of the key, two members of the same household
15	 * (same householdId) with different telephones are distinct contacts and are both allowed; only two
16	 * owners that are the same contact (matching telephone and email) collide.
17	 *
18	 * <p>Runs after {@link RequireOwnerFields} has normalized and published the body and before
19	 * {@link BuildOwner}/{@link SaveOwner} persist the new owner.
20	 */
21	public class RequireUniqueIdentity {
22	
23	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
24	            throws DuplicateIdentityException {
25	        String contactKey = OwnerIdentity.contactKey(request.getTelephone(), request.getEmail());
26	        for (Owner existing : ownerRepository.findAll()) {
27	            String existingKey = OwnerIdentity.contactKey(existing.getTelephone(), existing.getEmail());
28	            if (contactKey.equals(existingKey)) {
29	                throw new DuplicateIdentityException(
30	                        "An owner with the same identity already exists");
31	            }
32	        }
33	    }
34	}
