26	            throws MissingFieldsException, InvalidTelephoneException, InvalidEmailException {
27	        request.setAddress(OwnerAddress.normalize(request.getAddress()));
28	        List<String> missing = new ArrayList<>();
29	        if (isBlank(request.getFirstName())) {
30	            missing.add("firstName");
31	        }
32	        if (isBlank(request.getLastName())) {
33	            missing.add("lastName");
34	        }
35	        if (isBlank(request.getAddress())) {
36	            missing.add("address");
37	        }
38	        if (isBlank(request.getCity())) {
39	            missing.add("city");
40	        }
41	        if (isBlank(request.getTelephone())) {
42	            missing.add("telephone");
43	        }
44	        if (!missing.isEmpty()) {
45	            throw new MissingFieldsException(missing);
46	        }
47	        request.setTelephone(OwnerTelephone.toE164(request.getTelephone()));
48	        request.setEmail(OwnerEmail.normalize(request.getEmail()));
49	        validated.set(request);
50	    }
51	
52	    private static boolean isBlank(String value) {
53	        return value == null || value.isBlank();
54	    }
55	}
